DELIMITER $$
CREATE TRIGGER `after_delete_product` AFTER DELETE ON `tbloproducts` FOR EACH ROW BEGIN
    -- Update oqty and ovalue in tbljobs
    UPDATE tbljobs
    SET 
        oqty = (SELECT IFNULL(SUM(qty), 0) FROM tbloproducts WHERE jobid = OLD.jobid),
        ovalue = (SELECT IFNULL(SUM(total), 0) FROM tbloproducts WHERE jobid = OLD.jobid)
    WHERE jobid = OLD.jobid;

    -- Update vat, netvalue, and balance in tbljobs
    UPDATE tbljobs
    SET 
        vat = (ovalue - discount) * 0.15,
        netvalue = ovalue + vat,
        balance = netvalue - paid_amount
    WHERE jobid = OLD.jobid;
END
$$
DELIMITER ;
